<?php
namespace WPKit\SiteDoctor\Scanners; use WPKit\SiteDoctor\{SiteDoctorIssue,SiteDoctorScanner}; if(!defined('ABSPATH'))exit;
final class LinkScanner implements SiteDoctorScanner{public function id():string{return 'links';}public function label():string{return 'Links';}public function scan():array{$o=[];$home=home_url('/');$r=wp_safe_remote_get($home,['timeout'=>8]);if(is_wp_error($r))return $o;$h=wp_remote_retrieve_body($r);preg_match_all('/<a[^>]+href=["\']([^"\']+)["\']/i',$h,$m);$count=0;foreach(array_unique($m[1]??[]) as $url){if($count++>=20)break;if(strpos($url,'#')===0||strpos($url,'mailto:')===0||strpos($url,'tel:')===0)continue;$u=wp_http_validate_url($url)?$url:wp_make_link_relative($url);if(!preg_match('#^https?://#i',$u))$u=home_url(ltrim($u,'/'));$rr=wp_safe_remote_head($u,['timeout'=>4,'redirection'=>2]);if(is_wp_error($rr))continue;$code=(int)wp_remote_retrieve_response_code($rr);if($code>=400)$o[]=$this->i('broken-link-'.md5($u),'links',$code>=500?'high':'medium','manual_only','Broken link detected','A homepage link returned HTTP '.$code.': '.$u,'Review or update the link.');}return $o;}private function i($id,$c,$s,$r,$t,$d,$rec){return new SiteDoctorIssue(['id'=>$id,'category'=>$c,'severity'=>$s,'risk'=>$r,'title'=>$t,'description'=>$d,'recommendation'=>$rec]);}}
